import json
from pathlib import Path
p=Path('.domainry/builder/model-apply.json')
d=json.loads(p.read_text())
keys=('plane','service','runtime','contract','version','identity','receipt','signing')
def walk(x,path=''):
    if isinstance(x,dict):
        for k,v in x.items():
            q=f'{path}.{k}' if path else k
            if any(s in k.lower() for s in keys) and not isinstance(v,(dict,list)):
                print(q, '=', v)
            walk(v,q)
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,f'{path}[{i}]')
walk(d)
