import json,re,urllib.request,urllib.error
from pathlib import Path
base='http://127.0.0.1:19120'
desired=Path('.domainry/builder/runtime/acceptance-failure-secret').read_text().strip()
log=Path('.domainry/builder/runtime/runtime.log').read_text(errors='replace')
patterns=[r'(?i)(?:password|secret)["'^'"\\n:=]*[:=]\\s*[\"\\']?(["'^'"\\s\"\\']{8,})',r'(?i)password\\s+(["'^'"\\s]{8,})']
bootstrap=None
for pat in patterns:
 m=re.search(pat,log)
 if m and m.group(1) "'!= desired:
  bootstrap=m.group(1); break

def post(path,body,token=None,key=None):
 data=json.dumps(body).encode(); h={'"'Content-Type':'application/json'}
 if token: h['Authorization']='Bearer '+token
 if key: h['Idempotency-Key']=key
 req=urllib.request.Request(base+path,data=data,headers=h,method='POST')
 try:
  with urllib.request.urlopen(req) as r: return r.status,json.load(r)
 except urllib.error.HTTPError as e:
  try: b=json.load(e)
  except: b={'raw':e.read().decode(errors='replace')[:200]}
  return e.code,b

def token_for(email):
 for pw in [desired,bootstrap]:
  if not pw: continue
  s,b=post('/auth/login',{'workspace_id':'default','login':email,'password':pw})
  if s==200:
   tok=b.get('access_token') or b.get('data',{}).get('access_token')
   must=b.get('must_change_password') or b.get('data',{}).get('must_change_password')
   if must:
    s2,b2=post('/auth/change-password',{'current_password':pw,'new_password':desired},tok,'verify-password-'+email)
    if s2 not in (200,204): raise SystemExit('password change failed status '+str(s2)+' keys '+str(list(b2) if isinstance(b2,dict) else type(b2)))
    s,b=post('/auth/login',{'workspace_id':'default','login':email,'password':desired})
    if s"'!=200: raise SystemExit('"'post-change login failed '+str(s))
    tok=b.get('access_token') or b.get('data',{}).get('access_token')
   return tok
 raise SystemExit('login failed for '+email+' bootstrap_detected='+str(bool(bootstrap)))
tok=token_for('sales_director_demo@example.com')
req=urllib.request.Request(base+'/openapi.json',headers={'Authorization':'Bearer '+tok})
with urllib.request.urlopen(req) as r: api=json.load(r)
print('openapi',api.get('info',{}),'paths',len(api.get('paths',{})))
names=['LeadCreateRequest','LeadRecord','ActionRequest','ActionResult','PageResult','WorkflowTask','WorkflowTaskList','WorkflowDecisionRequest','ReportQueryRequest','ReportQueryResponse','ReportSummaryResponse','ReportExportPrepareRequest']
schemas=api.get('components',{}).get('schemas',{})
for name in names:
 if name in schemas: print('\\nSCHEMA '+name+'\\n'+json.dumps(schemas[name],indent=2)[:12000])
print('\\nMATCHING SCHEMAS')
for name in schemas:
 if any(x in name.lower() for x in ('lead','action','workflow','report','export','page')):
  print(name)
PY"

