// This file is initial project-owned business source. Domainry will never overwrite it.
package crm

import (
	"context"
	"math/big"
	"time"

	capabilities "github.com/domainry-eval/m1-crm/generated/capabilities"
	data "github.com/domainry-eval/m1-crm/generated/data"
	schema "github.com/domainry-eval/m1-crm/generated/schema"
)

// InitiateConversion implements the project-owned lead.initiate_conversion Handler.
func InitiateConversion(ctx context.Context, caps capabilities.InitiateConversionCapabilities, input capabilities.InitiateConversionInput) (capabilities.InitiateConversionOutput, error) {
	if caps.Execution == nil || caps.Lead == nil || caps.Customer == nil || caps.ConversionApproval == nil {
		return capabilities.InitiateConversionOutput{}, businessError("crm.conversion.capability_unavailable")
	}
	principal := caps.Execution.Principal()
	if !principal.Known || principal.UserID == "" {
		return capabilities.InitiateConversionOutput{}, businessError("crm.conversion.principal_required")
	}
	if !nonEmpty(input.RequestID) {
		return capabilities.InitiateConversionOutput{}, businessError("crm.conversion.request_id_required")
	}
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.InitiateConversionOutput{}, err
	}
	if lead.OwnerUser == nil || *lead.OwnerUser != principal.UserID {
		return capabilities.InitiateConversionOutput{}, businessError("crm.lead.not_owner")
	}
	if lead.Status != schema.LeadStatus("qualified") {
		return capabilities.InitiateConversionOutput{}, businessError("crm.conversion.lead_not_qualified")
	}
	if lead.EstimatedAmount == nil {
		return capabilities.InitiateConversionOutput{}, businessError("crm.conversion.amount_required")
	}
	amount, ok := new(big.Rat).SetString(string(*lead.EstimatedAmount))
	if !ok || amount.Sign() < 0 {
		return capabilities.InitiateConversionOutput{}, businessError("crm.conversion.amount_invalid")
	}
	threshold := new(big.Rat).SetInt64(100000)

	leadReference := schema.NewCustomerLeadIDReference(lead.ID)
	customerExists, err := caps.Customer.Exists(ctx, data.NewCustomerQuery().WhereLeadIDEqual(leadReference))
	if err != nil {
		return capabilities.InitiateConversionOutput{}, err
	}
	if customerExists {
		return capabilities.InitiateConversionOutput{}, businessError("crm.conversion.customer_exists")
	}

	if amount.Cmp(threshold) >= 0 {
		approvalLead := schema.NewConversionApprovalLeadIDReference(lead.ID)
		pendingExists, err := caps.ConversionApproval.Exists(ctx, data.NewConversionApprovalQuery().
			WhereLeadIDEqual(approvalLead).
			WhereStatusEqual(schema.ConversionApprovalStatus("pending")))
		if err != nil {
			return capabilities.InitiateConversionOutput{}, err
		}
		if pendingExists {
			return capabilities.InitiateConversionOutput{}, businessError("crm.conversion.approval_pending")
		}
		requester := schema.NewConversionApprovalRequesterUserReference(schema.IdentityUserID(principal.UserID))
		approval, err := caps.ConversionApproval.Create(ctx, schema.CreateConversionApproval{
			AmountSnapshot: schema.ConversionApprovalAmountSnapshot(*lead.EstimatedAmount),
			LeadID:         approvalLead,
			RequesterUser:  &requester,
			Status:         schema.ConversionApprovalStatus("pending"),
		})
		if err != nil {
			return capabilities.InitiateConversionOutput{}, err
		}
		approvalID := approval.ID
		return capabilities.InitiateConversionOutput{
			ApprovalID: &approvalID,
			Route:      schema.LeadInitiateConversionRoute("approval"),
			Status:     schema.LeadInitiateConversionStatus("qualified"),
		}, nil
	}

	customer, err := caps.Customer.Create(ctx, customerFromLead(lead))
	if err != nil {
		return capabilities.InitiateConversionOutput{}, err
	}
	updated, err := caps.Lead.ConditionalUpdate(ctx, data.NewLeadUpdate(lead.ID).
		SetStatus(schema.LeadStatus("converted")).
		SetStatusChangedAt(time.Now().UTC()).
		RequireOwnerUserEqual(principal.UserID, "crm.conversion.owner_changed").
		RequireStatusEqual(schema.LeadStatus("qualified"), "crm.conversion.state_changed"))
	if err != nil {
		return capabilities.InitiateConversionOutput{}, err
	}
	customerID := customer.ID
	return capabilities.InitiateConversionOutput{
		CustomerID: &customerID,
		Route:      schema.LeadInitiateConversionRoute("direct"),
		Status:     schema.LeadInitiateConversionStatus(updated.Status),
	}, nil
}

func customerFromLead(lead schema.Lead) schema.CreateCustomer {
	var source *schema.CustomerLeadSource
	if lead.Source != nil {
		value := schema.CustomerLeadSource(*lead.Source)
		source = &value
	}
	var owner *schema.CustomerOwnerUserReference
	if lead.OwnerUser != nil {
		value := schema.NewCustomerOwnerUserReference(schema.IdentityUserID(*lead.OwnerUser))
		owner = &value
	}
	return schema.CreateCustomer{
		CompanyName:         lead.CompanyName,
		ContactName:         lead.ContactName,
		ContactPhone:        lead.ContactPhone,
		ConvertedAmount:     schema.CustomerConvertedAmount(*lead.EstimatedAmount),
		LeadID:              schema.NewCustomerLeadIDReference(lead.ID),
		LeadSource:          source,
		OwnerDepartmentID:   lead.OwnerDepartmentID,
		OwnerDepartmentPath: lead.OwnerDepartmentPath,
		OwnerUser:           owner,
	}
}
