package crm

import (
	"context"
	"strings"
	"time"

	capabilities "github.com/domainry-eval/m1-crm/generated/capabilities"
	data "github.com/domainry-eval/m1-crm/generated/data"
	schema "github.com/domainry-eval/m1-crm/generated/schema"
)

// ResolveConversion implements the project-owned conversion_approval.resolve_conversion Handler.
func ResolveConversion(ctx context.Context, caps capabilities.ResolveConversionCapabilities, input capabilities.ResolveConversionInput) (capabilities.ResolveConversionOutput, error) {
	if caps.Execution == nil || caps.ConversionApproval == nil || caps.Lead == nil || caps.Customer == nil || caps.Notifications == nil {
		return capabilities.ResolveConversionOutput{}, businessError("crm.approval.capability_unavailable")
	}
	principal := caps.Execution.Principal()
	if !principal.Known || principal.UserID == "" {
		return capabilities.ResolveConversionOutput{}, businessError("crm.approval.principal_required")
	}
	if !nonEmpty(input.RequestID) {
		return capabilities.ResolveConversionOutput{}, businessError("crm.approval.request_id_required")
	}
	resolution := string(input.Resolution)
	if resolution != "approved" && resolution != "rejected" {
		return capabilities.ResolveConversionOutput{}, businessError("crm.approval.resolution_invalid")
	}
	if resolution == "rejected" && (input.Comment == nil || !nonEmpty(*input.Comment)) {
		return capabilities.ResolveConversionOutput{}, businessError("crm.approval.rejection_reason_required")
	}

	approval, err := caps.ConversionApproval.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.ResolveConversionOutput{}, err
	}
	if approval.Status != schema.ConversionApprovalStatus("pending") {
		return capabilities.ResolveConversionOutput{}, businessError("crm.approval.already_resolved")
	}
	if approval.RequesterUser == nil {
		return capabilities.ResolveConversionOutput{}, businessError("crm.approval.requester_required")
	}
	lead, err := caps.Lead.GetForUpdate(ctx, approval.LeadID.ID())
	if err != nil {
		return capabilities.ResolveConversionOutput{}, err
	}
	if lead.Status != schema.LeadStatus("qualified") {
		return capabilities.ResolveConversionOutput{}, businessError("crm.approval.lead_not_qualified")
	}
	if lead.EstimatedAmount == nil || string(*lead.EstimatedAmount) != string(approval.AmountSnapshot) {
		return capabilities.ResolveConversionOutput{}, businessError("crm.approval.amount_changed")
	}

	now := time.Now().UTC()
	approvalMutation := data.NewConversionApprovalUpdate(approval.ID).
		SetStatus(schema.ConversionApprovalStatus(resolution)).
		SetDecisionActor(principal.UserID).
		SetDecidedAt(now).
		RequireStatusEqual(schema.ConversionApprovalStatus("pending"), "crm.approval.decision_conflict")
	if input.Comment != nil {
		approvalMutation = approvalMutation.SetRejectionReason(strings.TrimSpace(*input.Comment))
	}

	var customerID *schema.CustomerID
	leadStatus := schema.LeadStatus("qualified")
	if resolution == "approved" {
		exists, err := caps.Customer.Exists(ctx, data.NewCustomerQuery().WhereLeadIDEqual(schema.NewCustomerLeadIDReference(lead.ID)))
		if err != nil {
			return capabilities.ResolveConversionOutput{}, err
		}
		if exists {
			return capabilities.ResolveConversionOutput{}, businessError("crm.approval.customer_exists")
		}
		customer, err := caps.Customer.Create(ctx, customerFromLead(lead))
		if err != nil {
			return capabilities.ResolveConversionOutput{}, err
		}
		updatedLead, err := caps.Lead.ConditionalUpdate(ctx, data.NewLeadUpdate(lead.ID).
			SetStatus(schema.LeadStatus("converted")).
			SetStatusChangedAt(now).
			RequireStatusEqual(schema.LeadStatus("qualified"), "crm.approval.lead_conflict"))
		if err != nil {
			return capabilities.ResolveConversionOutput{}, err
		}
		leadStatus = updatedLead.Status
		value := customer.ID
		customerID = &value
	}

	updatedApproval, err := caps.ConversionApproval.ConditionalUpdate(ctx, approvalMutation)
	if err != nil {
		return capabilities.ResolveConversionOutput{}, err
	}
	eventType := "crm.conversion_approved"
	variables := []capabilities.ResolveConversionNotificationVariable{{Key: "company_name", StringValue: &lead.CompanyName}}
	if resolution == "rejected" {
		eventType = "crm.conversion_rejected"
		reason := strings.TrimSpace(*input.Comment)
		variables = append(variables, capabilities.ResolveConversionNotificationVariable{Key: "reason", StringValue: &reason})
	}
	sourceEventID := string(approval.ID) + ":" + resolution
	_, err = caps.Notifications.Dispatch(ctx, capabilities.ResolveConversionNotificationIntent{
		EventType:        eventType,
		SourceEventID:    sourceEventID,
		RecipientUserIDs: []string{string(approval.RequesterUser.ID())},
		Surface:          "business_workspace",
		SubjectObjectKey: "conversion_approval",
		SubjectRecordID:  string(approval.ID),
		SubjectVersion:   updatedApproval.UpdatedAt,
		DedupeKey:        sourceEventID,
		GroupKey:         string(approval.LeadID.ID()),
		OccurredAt:       now,
		Variables:        variables,
	})
	if err != nil {
		return capabilities.ResolveConversionOutput{}, err
	}
	return capabilities.ResolveConversionOutput{
		ApprovalStatus: schema.ConversionApprovalResolveConversionApprovalStatus(updatedApproval.Status),
		CustomerID:     customerID,
		LeadStatus:     schema.ConversionApprovalResolveConversionLeadStatus(leadStatus),
	}, nil
}
