		return capabilities.SendStaleReminderOutput{}, businessError("crm.reminder.capability_unavailable")
	}
	principal := caps.Execution.Principal()
	if !principal.Known || !nonEmpty(input.RequestID) {
		return capabilities.SendStaleReminderOutput{}, businessError("crm.reminder.context_invalid")
	}
	lead, err := caps.Lead.Get(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.SendStaleReminderOutput{}, err
	}
	if lead.Status != schema.LeadStatus("contacted") || lead.StatusChangedAt == nil || !input.ScheduledAt.After(lead.StatusChangedAt.Add(7*24*time.Hour)) {
		return capabilities.SendStaleReminderOutput{Reminded: false}, nil
	}
	if lead.OwnerUser == nil || *lead.OwnerUser == "" {
		return capabilities.SendStaleReminderOutput{}, businessError("crm.reminder.owner_required")
	}
	businessDate := input.BusinessDate.UTC()
	dedupeKey := string(lead.ID) + ":" + businessDate.Format("2006-01-02")
	exists, err := caps.LeadReminderReceipt.Exists(ctx, data.NewLeadReminderReceiptQuery().WhereDedupeKeyEqual(dedupeKey))
	if err != nil {
		return capabilities.SendStaleReminderOutput{}, err
	}
	if exists {
		return capabilities.SendStaleReminderOutput{Reminded: false}, nil
	}
	recipient := schema.NewLeadReminderReceiptRecipientUserReference(schema.IdentityUserID(*lead.OwnerUser))
	receipt, err := caps.LeadReminderReceipt.Create(ctx, schema.CreateLeadReminderReceipt{
		BusinessDate:        businessDate,
		DedupeKey:           dedupeKey,
		LeadID:              schema.NewLeadReminderReceiptLeadIDReference(lead.ID),
		OwnerDepartmentID:   lead.OwnerDepartmentID,
		OwnerDepartmentPath: lead.OwnerDepartmentPath,
		RecipientUser:       &recipient,
	})
	if err != nil {
		return capabilities.SendStaleReminderOutput{}, err
	}
	_, err = caps.Notifications.Dispatch(ctx, capabilities.SendStaleReminderNotificationIntent{
		EventType:        "crm.stale_lead_reminder",
		SourceEventID:    dedupeKey,
		RecipientUserIDs: []string{*lead.OwnerUser},
		Surface:          "business_workspace",
		SubjectObjectKey: "lead",
		SubjectRecordID:  string(lead.ID),
		SubjectVersion:   lead.UpdatedAt,
		DedupeKey:        dedupeKey,
		GroupKey:         string(lead.ID),
		Alert:            true,
		OccurredAt:       input.ScheduledAt,
		Variables:        []capabilities.SendStaleReminderNotificationVariable{{Key: "company_name", StringValue: &lead.CompanyName}},
	})
	if err != nil {
		return capabilities.SendStaleReminderOutput{}, err
	}
	receiptID := receipt.ID
	return capabilities.SendStaleReminderOutput{ReceiptID: &receiptID, Reminded: true}, nil
}
