func TestBF08GovernedExportZeroNormalAnd1000Boundary(t *testing.T) {
	east := login(t, eastEmail)
	director := login(t, directorEmail)
	prefix := unique("bf08")

	zeroAudit := requestExportAudit(t, director, prefix+"-zero")
	zeroHeaders, zeroCSV, zeroStatus := prepareExport(t, director, zeroAudit, prefix+"-zero", map[string]any{
		"purpose":   "BF-08 zero-row boundary",
		"freshness": map[string]any{"mode": "realtime"},
		"filters":   []any{map[string]any{"dimension_key": "lead_id", "operator": "eq", "values": []string{prefix + "-does-not-exist"}}},
	})
	if zeroStatus != http.StatusOK || headerInt(zeroHeaders, "X-Report-Export-Row-Count") != 0 || len(zeroCSV) == 0 {
		t.Fatalf("zero-row synchronous export invalid: status=%d rows=%d body=%s", zeroStatus, headerInt(zeroHeaders, "X-Report-Export-Row-Count"), bounded(zeroCSV))
	}

	total := intValue(queryDetailReport(t, director, 1, "")["total"])
	if total > 1000 {
		t.Fatalf("fresh BF-08 cohort already exceeds synchronous boundary: total=%d", total)
	}
	createLeadsConcurrently(t, east, prefix, 1000-total)
	if got := intValue(queryDetailReport(t, director, 1, "")["total"]); got != 1000 {
		t.Fatalf("failed to construct exact 1000-row boundary: got=%d", got)
	}
	syncAudit := requestExportAudit(t, director, prefix+"-sync")
	syncHeaders, syncCSV, syncStatus := prepareExport(t, director, syncAudit, prefix+"-sync", map[string]any{
		"purpose":   "BF-08 exact 1000-row synchronous boundary",
		"freshness": map[string]any{"mode": "realtime"},
	})
	if syncStatus != http.StatusOK || headerInt(syncHeaders, "X-Report-Export-Row-Count") != 1000 || syncHeaders.Get("X-Content-SHA256") == "" || syncHeaders.Get("X-Report-Export-Download-Token") == "" {
		t.Fatalf("1000-row synchronous export invalid: status=%d headers=%v body=%s", syncStatus, syncHeaders, bounded(syncCSV))
	}
	reader := csv.NewReader(strings.NewReader(string(syncCSV)))
	rows, err := reader.ReadAll()
	if err != nil || len(rows) != 1001 {
		t.Fatalf("1000-row CSV durability invalid: rows=%d err=%v", len(rows), err)
	}
	downloadPath := "/report-exports/downloads/" + url.PathEscape(syncHeaders.Get("X-Report-Export-Download-Token"))
	_, downloaded := director.json("GET", downloadPath, "", nil, nil, http.StatusOK)
	if len(downloaded) != len(syncCSV) {
		t.Fatalf("governed download differs from prepared artifact: prepared=%d downloaded=%d", len(syncCSV), len(downloaded))
	}

	createLead(t, east, prefix+"-row-1001", "42000.00", prefix+"-row-1001")
	if got := intValue(queryDetailReport(t, director, 1, "")["total"]); got != 1001 {
		t.Fatalf("failed to construct exact 1001-row boundary: got=%d", got)
	}
	asyncAudit := requestExportAudit(t, director, prefix+"-async")
	_, asyncBody, asyncStatus := prepareExport(t, director, asyncAudit, prefix+"-async", map[string]any{
		"purpose":   "BF-08 exact 1001-row asynchronous boundary",
		"freshness": map[string]any{"mode": "realtime"},
	})
	if asyncStatus != http.StatusAccepted {
		t.Fatalf("1001-row export must be asynchronous: status=%d body=%s", asyncStatus, bounded(asyncBody))
	}
	var job map[string]any
	mustJSON(t, asyncBody, &job)
	jobID := nestedString(job, "id")
	if jobID == "" {
		jobID = nestedString(job, "batch_job_id")
	}
	if jobID == "" {
		t.Fatalf("asynchronous export returned no job id: %#v", job)
	}
	poll(t, 45*time.Second, "1001-row export completion", func() bool {
		_, body := director.json("GET", "/report-exports/"+url.PathEscape(jobID), "", nil, nil, http.StatusOK)
		mustJSON(t, body, &job)
		if nestedString(job, "status") == "failed" {
			t.Fatalf("asynchronous export failed: %s", bounded(body))
		}
		return nestedString(job, "status") == "completed"
	})
	if intValue(job["rows_exported"]) != 1001 || nestedString(job, "download_token") == "" || nestedString(job, "content_sha256") == "" {
		t.Fatalf("completed asynchronous export invalid: %#v", job)
	}
	_, asyncCSV := director.json("GET", "/report-exports/downloads/"+url.PathEscape(nestedString(job, "download_token")), "", nil, nil, http.StatusOK)
	if len(asyncCSV) == 0 {
		t.Fatal("asynchronous governed download was empty")
	}
}

