func prepareExport(t *testing.T, director *runtimeClient, auditID, key string, scope map[string]any) (http.Header, []byte, int) {
	t.Helper()
	status, headers, body := rawRequest(t, director.base, "POST", "/reports/lead_detail_report/exports/lead/prepare", director.token, key+"-prepare", map[string]string{
		"X-Operation-Reason":       "M1 CRM business-flow verification",
		"X-Operation-Confirmation": "confirmed",
	}, map[string]any{"audit_id": auditID, "scope": scope})
	return headers, body, status
}

func createLeadsConcurrently(t *testing.T, east *runtimeClient, prefix string, count int) {
	t.Helper()
	if count <= 0 {
		return
	}
	const workers = 12
	jobs := make(chan int)
	errors := make(chan string, workers)
	var wait sync.WaitGroup
	for worker := 0; worker < workers; worker++ {
		wait.Add(1)
		go func() {
			defer wait.Done()
			for index := range jobs {
				key := prefix + "-fixture-" + strconv.Itoa(index)
				status, _, body := rawRequest(t, east.base, "POST", "/objects/lead/records", east.token, key, nil, map[string]any{"data": map[string]any{
					"company_name":     key,
					"estimated_amount": "1000.00",
					"source":           "outbound",
					"status":           "new",
				}})
				if status != http.StatusOK && status != http.StatusCreated {
					errors <- fmt.Sprintf("index=%d status=%d body=%s", index, status, bounded(body))
					return
				}
			}
		}()
	}
	for index := 0; index < count; index++ {
		jobs <- index
	}
	close(jobs)
	wait.Wait()
	close(errors)
	for failure := range errors {
		t.Fatal(failure)
	}
}

func headerInt(headers http.Header, key string) int {
	value, _ := strconv.Atoi(headers.Get(key))
	return value
}

func intValue(value any) int {
	switch item := value.(type) {
	case float64:
		return int(item)
	case int:
		return item
	case json.Number:
		value, _ := item.Int64()
		return int(value)
	case string:
		value, _ := strconv.Atoi(item)
		return value
	}
	return 0
}
