)

const workspaceID = "default"

var sequence atomic.Uint64
var expectedActionVersions sync.Map

type runtimeClient struct {
	t     *testing.T
	base  string
	token string
}

type record struct {
	ID        string         `json:"id"`
	ObjectKey string         `json:"object_key"`
	Data      map[string]any `json:"data"`
	CreatedAt string         `json:"created_at"`
	UpdatedAt string         `json:"updated_at"`
}

type pageResult struct {
	Items    []record `json:"items"`
	Page     int      `json:"page"`
	PageSize int      `json:"page_size"`
	Total    int      `json:"total"`
	HasNext  bool     `json:"has_next"`
}

func runtimeURL(t *testing.T) string {
	t.Helper()
	base := strings.TrimRight(os.Getenv("DOMAINRY_RUNTIME_URL"), "/")
	if base == "" {
		t.Skip("DOMAINRY_RUNTIME_URL is required for managed-Runtime business-flow verification")
	}
	return base
}

func login(t *testing.T, email string) *runtimeClient {
	t.Helper()
	base := runtimeURL(t)
	desired := os.Getenv("DOMAINRY_ACCEPTANCE_PASSWORD")
	bootstrap := os.Getenv("DOMAINRY_ACCEPTANCE_BOOTSTRAP_PASSWORD")
	if desired == "" || bootstrap == "" {
		t.Fatal("DOMAINRY_ACCEPTANCE_PASSWORD and DOMAINRY_ACCEPTANCE_BOOTSTRAP_PASSWORD are required")
	}
	for _, password := range []string{desired, bootstrap} {
		status, _, body := rawRequest(t, base, "POST", "/auth/login", "", "", nil, map[string]any{
			"workspace_id": workspaceID,
			"login":        email,
			"password":     password,
		})
		if status != http.StatusOK {
			continue
		}
		var session map[string]any
		mustJSON(t, body, &session)
		token := nestedString(session, "access_token")
		if token == "" {
			t.Fatalf("login for %s returned no access_token", email)
		}
		if nestedBool(session, "must_change_password") {
			status, _, changeBody := rawRequest(t, base, "POST", "/auth/change-password", token, "bf-password-"+safeKey(email), nil, map[string]any{
				"current_password": password,
				"new_password":     desired,
			})
			if status != http.StatusOK && status != http.StatusNoContent {
				t.Fatalf("change password for %s: status=%d body=%s", email, status, bounded(changeBody))
			}
			status, _, body = rawRequest(t, base, "POST", "/auth/login", "", "", nil, map[string]any{
				"workspace_id": workspaceID,
				"login":        email,
				"password":     desired,
			})
			if status != http.StatusOK {
				t.Fatalf("login after password change for %s: status=%d body=%s", email, status, bounded(body))
			}
			mustJSON(t, body, &session)
			token = nestedString(session, "access_token")
		}
		return &runtimeClient{t: t, base: base, token: token}
	}
	t.Fatalf("formal Runtime login failed for %s", email)
	return nil
}

func (c *runtimeClient) json(method, path, idempotency string, extra map[string]string, input any, expected ...int) (http.Header, []byte) {
	c.t.Helper()
	status, headers, body := rawRequest(c.t, c.base, method, path, c.token, idempotency, extra, input)
	for _, want := range expected {
		if status == want {
			return headers, body
		}
	}
	c.t.Fatalf("%s %s: status=%d expected=%v body=%s", method, path, status, expected, bounded(body))
	return nil, nil
}

func rawRequest(t *testing.T, base, method, path, token, idempotency string, extra map[string]string, input any) (int, http.Header, []byte) {
	t.Helper()
	var body io.Reader
	if input != nil {
		payload, err := json.Marshal(input)
		if err != nil {
			t.Fatal(err)
		}
		body = bytes.NewReader(payload)
	}
	req, err := http.NewRequest(method, base+path, body)
	if err != nil {
		t.Fatal(err)
	}
	if input != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	if idempotency != "" {
		req.Header.Set("Idempotency-Key", idempotency)
	}
	for key, value := range extra {
		req.Header.Set(key, value)
	}
	httpClient := &http.Client{Timeout: 45 * time.Second}
	resp, err := httpClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	payload, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatal(err)
	}
	return resp.StatusCode, resp.Header.Clone(), payload
}

