// TestBF03HighValueConversionApproval is intentionally numbered first because it
// is executed alone as the highest-risk canary before the rest of the suite.
func TestBF03HighValueConversionApproval(t *testing.T) {
	east := login(t, eastEmail)
	director := login(t, directorEmail)
	prefix := unique("bf03")
	lead := createLead(t, east, prefix+"-high", "100000.00", prefix+"-create")
	advanceToQualified(t, east, lead.ID, prefix)

	result := recordAction(t, east, "lead", lead.ID, "lead.initiate_conversion", prefix+"-initiate-transport", map[string]any{
		"request_id": prefix + "-initiate",
	}, http.StatusOK)
	approvalID := nestedString(result, "approval_id")
	if approvalID == "" || nestedString(result, "route") != "approval" {
		t.Fatalf("high-value conversion did not return approval route: %#v", result)
	}
	replay := recordAction(t, east, "lead", lead.ID, "lead.initiate_conversion", prefix+"-initiate-transport", map[string]any{
		"request_id": prefix + "-initiate",
	}, http.StatusOK)
	if nestedString(replay, "approval_id") != approvalID {
		t.Fatalf("transport idempotency replay changed approval: first=%s replay=%#v", approvalID, replay)
	}
	current, _ := getRecord(t, east, "lead", lead.ID, http.StatusOK)
	if current.Data["status"] != "qualified" {
		t.Fatalf("lead changed before decision: %#v", current.Data)
	}

	taskID := waitForApprovalTask(t, director, approvalID)
	director.json("POST", "/business/workflow/tasks/"+url.PathEscape(taskID)+"/approve", prefix+"-approve", nil, map[string]any{
		"comment": "BF-03 canary approved",
	}, http.StatusOK)
	poll(t, 15*time.Second, "approved lead conversion", func() bool {
		current, status := getRecord(t, east, "lead", lead.ID, http.StatusOK)
		return status == http.StatusOK && current.Data["status"] == "converted"
	})
	approval, _ := getRecord(t, director, "conversion_approval", approvalID, http.StatusOK)
	if approval.Data["status"] != "approved" {
		t.Fatalf("approval not durable: %#v", approval.Data)
	}
	if countRelatedRecords(t, director, "customer", lead.ID) != 1 {
		t.Fatal("approved lead must have exactly one durable customer")
	}
	poll(t, 10*time.Second, "approval notification", func() bool {
		return notificationCount(t, east, "crm.conversion_approved", approvalID) == 1
	})
	_, _, body := rawRequest(t, director.base, "POST", "/business/workflow/tasks/"+url.PathEscape(taskID)+"/approve", director.token, prefix+"-approve-retry", nil, map[string]any{"comment": "retry"})
	if countRelatedRecords(t, director, "customer", lead.ID) != 1 || notificationCount(t, east, "crm.conversion_approved", approvalID) != 1 {
		t.Fatalf("repeated approval produced duplicate durable effects: response=%s", bounded(body))
	}
}

func TestBF01LeadOwnershipLifecycleAndScope(t *testing.T) {
	east := login(t, eastEmail)
	north := login(t, northEmail)
	director := login(t, directorEmail)
	prefix := unique("bf01")
	company := prefix + "-east-owned"
	created := createLead(t, east, company, "50000.00", prefix+"-create")
	replayed := createLead(t, east, company, "50000.00", prefix+"-create")
	if replayed.ID != created.ID {
		t.Fatalf("create idempotency failed: %s != %s", replayed.ID, created.ID)
	}
	getRecord(t, east, "lead", created.ID, http.StatusOK)
	getRecord(t, director, "lead", created.ID, http.StatusOK)
	getRecord(t, north, "lead", created.ID, http.StatusForbidden, http.StatusNotFound)

	recordAction(t, east, "lead", created.ID, "lead.update_owned_lead", prefix+"-update", map[string]any{
		"request_id": prefix + "-update", "contact_name": "更新后联系人", "estimated_amount": "51000.25",
	}, http.StatusOK)
	recordAction(t, east, "lead", created.ID, "lead.advance_owned_lead", prefix+"-advance", map[string]any{
		"request_id": prefix + "-advance", "target_status": "contacted",
	}, http.StatusOK)
	after, _ := getRecord(t, east, "lead", created.ID, http.StatusOK)
	if after.Data["contact_name"] != "更新后联系人" || after.Data["status"] != "contacted" || fmt.Sprint(after.Data["estimated_amount"]) != "51000.25" {
		t.Fatalf("durable update/readback mismatch: %#v", after.Data)
	}
	status, _, _ := rawRequest(t, north.base, "POST", "/objects/lead/records/"+url.PathEscape(created.ID)+"/actions/lead.update_owned_lead", north.token, prefix+"-north-denied", nil, map[string]any{
		"data": map[string]any{"request_id": prefix + "-north-denied", "contact_name": "越权修改", "expected_updated_at": after.UpdatedAt},
	})
	if status != http.StatusForbidden && status != http.StatusNotFound {
		t.Fatalf("cross-department mutation must be denied, status=%d", status)
	}
	unchanged, _ := getRecord(t, east, "lead", created.ID, http.StatusOK)
	if unchanged.Data["contact_name"] != "更新后联系人" {
		t.Fatalf("denied mutation changed durable state: %#v", unchanged.Data)
	}
}

