func TestBF05DepartmentGlobalScopeAndPagination(t *testing.T) {
	east := login(t, eastEmail)
	north := login(t, northEmail)
	director := login(t, directorEmail)
	prefix := unique("bf05")
	eastLead := createLead(t, east, prefix+"-east", "22000.00", prefix+"-east-create")
	northLead := createLead(t, north, prefix+"-north", "33000.00", prefix+"-north-create")
	eastPage := listRecords(t, east, "lead", 1, 200)
	northPage := listRecords(t, north, "lead", 1, 200)
	directorFirst := listRecords(t, director, "lead", 1, 1)
	if !pageContains(eastPage, eastLead.ID) || pageContains(eastPage, northLead.ID) || !pageContains(northPage, northLead.ID) || pageContains(northPage, eastLead.ID) {
		t.Fatalf("department list scope invalid: east=%d north=%d", eastPage.Total, northPage.Total)
	}
	if directorFirst.PageSize != 1 || directorFirst.Total < eastPage.Total+northPage.Total || !directorFirst.HasNext {
		t.Fatalf("director global/pagination metadata invalid: %#v", directorFirst)
	}
	report := queryDetailReport(t, director, 1, "")
	if intValue(report["page_size"]) != 1 || intValue(report["total"]) < directorFirst.Total || report["total_semantics"] != "exact" || nestedString(report, "next_cursor") == "" {
		t.Fatalf("report pagination metadata invalid: %#v", report)
	}
	next := queryDetailReport(t, director, 1, nestedString(report, "next_cursor"))
	if intValue(next["row_count"]) != 1 {
		t.Fatalf("second report page invalid: %#v", next)
	}
}

